// Best-effort read of n8n's Error Trigger payload -- its exact shape has
// varied across n8n versions (same caveat as the Loop Leads output-order
// note in the main workflow's README). After importing both workflows,
// trigger a real failure (e.g. a bad APIFY_TOKEN) and check this node's
// output against the paths below -- adjust if your n8n version differs.
//
// The point of this node existing at all: without it, a crash in the main
// workflow (an Apify/Airtable/OpenAI call that exhausts its retries) is
// visible only in n8n's own execution log, which nobody checks day to day.
// This turns that into a "Failed" row in the same Runs table the healthy
// path writes to, so the dashboard can surface it.
const e = $json.execution || {};
const err = e.error || {};
const wf = $json.workflow || {};

return [{ json: {
  runId: e.id || 'unknown',
  trigger: ($json.trigger && $json.trigger.mode) || e.mode || 'Unknown',
  startedAt: e.startedAt || $now.toISO(),
  endedAt: $now.toISO(),
  durationSec: '',
  overallStatus: 'Failed',
  sourceStatus: 'Unknown -- workflow crashed before reaching source-stats collection',
  itemsDiscovered: '',
  itemsFiltered: '',
  newOpportunities: '',
  duplicates: '',
  aiAnalyses: '',
  aiFailures: '',
  errors: (err.node && err.node.name ? err.node.name + ': ' : '') + (err.message || ('Unknown error -- check this execution in n8n: ' + (e.url || wf.id || ''))),
}}];
